"""Execute PAL audio setup/SetCDVolume through their SDK MMIO writes.

Only numeric register results are emitted; no retail instructions are copied.
This uses the existing bounded R3000 interpreter, including delay slots.
It establishes register programming, not the analog waveform or CD DSP.
"""
import argparse
import hashlib
import json
from pathlib import Path

from generate_combat_reference import ArmourMachine

SEGMENT_SHA = "2dbdb53efd709a4cb5930ce91a39b55e8edad162c5fb773a7c6fa164a960fda8"


class AudioMachine(ArmourMachine):
    def __init__(self, image):
        super().__init__(image)
        self.spu, self.cd = {}, {}
        self.bank = 0
        self.trace = []
        self.r[28], self.r[29] = 0x800ae600, 0x801ff000

    def intercept(self, pc):
        return False  # execute the SDK routines too

    def read(self, address, size, sign=False):
        physical = address & 0x1fffffff
        if 0x1f801c00 <= physical < 0x1f801e60:
            if size != 2:
                raise ValueError("Unexpected SPU access width")
            return self.spu.get(physical, 0)
        return super().read(address, size, sign)

    def write(self, address, size, value):
        physical = address & 0x1fffffff
        value &= (1 << (8 * size)) - 1
        if 0x1f801c00 <= physical < 0x1f801e60:
            if size != 2:
                raise ValueError("Unexpected SPU access width")
            self.spu[physical] = value
        elif 0x1f801800 <= physical <= 0x1f801803:
            if size != 1:
                raise ValueError("Unexpected CD access width")
            if physical == 0x1f801800:
                self.bank = value & 3
            else:
                self.cd[self.bank, physical] = value
        else:
            return super().write(address, size, value)
        self.trace.append({"address": f"0x{physical:08x}", "bytes": size,
                           "bank": self.bank, "value": value})


def generate(image):
    if hashlib.sha256(image).hexdigest() != SEGMENT_SHA:
        raise ValueError("Expected the PAL SLES-01534 loaded segment")
    main = AudioMachine(image)
    main.run(0x8007248c, stop=0x800724a8)
    cd = AudioMachine(image)
    cd.run(0x80071adc, stop=0x80071b0c)
    master = [main.spu[a] for a in (0x1f801d80, 0x1f801d82)]
    cd_input = [cd.spu[a] for a in (0x1f801db0, 0x1f801db2)]
    rows = []
    for stereo in (0, 1):
        values = []
        for volume in range(256):
            m = AudioMachine(image)
            m.write(0x800b333e, 2, stereo)
            m.r[4] = volume
            m.run(0x80071b9c)
            if m.cd.get((3, 0x1f801803)) != 0x20:
                raise ValueError("The CD matrix was not latched")
            values.append([m.cd[key] for key in (
                (2, 0x1f801802), (2, 0x1f801803),
                (3, 0x1f801801), (3, 0x1f801802))])
        rows.append(values)
    out = [
        "/* Numeric MMIO results from the PAL executable; no retail code.",
        f" * Segment SHA-256: {SEGMENT_SHA}",
        " * Generated by generate_audio_reference.py. See README.md. */",
        "static const u16 audio_reference_main[2] = {" +
        ", ".join(f"0x{x:04x}" for x in master) + "};",
        "static const u16 audio_reference_cd_input[2] = {" +
        ", ".join(f"0x{x:04x}" for x in cd_input) + "};",
        "/* [stereo][volume][L->L, L->R, R->R, R->L] */",
        "static const u8 audio_reference_atv[2][256][4] = {",
    ]
    for mode in rows:
        out.append("    {")
        for values in mode:
            out.append("        {" + ", ".join(f"0x{x:02x}" for x in values) + "},")
        out.append("    },")
    out += ["};", ""]
    trace = {"segment_sha256": SEGMENT_SHA, "main_setup": main.trace,
             "cd_setup": cd.trace, "atv_cases": 512,
             "entries": ["0x8007248c..0x800724a8", "0x80071adc..0x80071b0c", "0x80071b9c"]}
    return "\n".join(out), trace


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("segment", type=Path)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--trace-json", type=Path)
    args = parser.parse_args()
    expected, trace = generate(args.segment.read_bytes())
    output = Path(__file__).resolve().with_name("audio_register_reference.h")
    if args.check:
        if output.read_text(encoding="utf-8") != expected:
            raise SystemExit("Audio register fixture differs from native execution")
    else:
        output.write_text(expected, encoding="utf-8")
    if args.trace_json:
        args.trace_json.write_text(json.dumps(trace, indent=2) + "\n", encoding="utf-8")
    print("Verified native main/CD input gains and 512 latched CD matrix cases")


if __name__ == "__main__":
    main()
